let memories=[],settings={},view=new Date(),filter='Alle';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function fmt(d){return new Intl.DateTimeFormat('de-CH',{day:'2-digit',month:'long',year:'numeric'}).format(new Date(d+'T12:00'))}function iso(d){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}async function init(){[memories,settings]=await Promise.all([fetch('/data/memories.json').then(r=>r.json()),fetch('/data/settings.json').then(r=>r.json())]);memories.sort((a,b)=>new Date(b.date)-new Date(a.date));if($('#heroLine'))$('#heroLine').textContent=settings.heroLine||'';if($('#days')){countdown();setInterval(countdown,30000)}if($('#cards'))renderCards();if($('#calendar'))renderCalendar();if($('#flashCard'))flashback()}function countdown(){let x=Math.max(0,new Date(settings.graduationDate+'T12:00')-new Date());$('#days').textContent=Math.floor(x/864e5);$('#hours').textContent=Math.floor(x/36e5)%24;$('#mins').textContent=Math.floor(x/6e4)%60}function renderCards(){let list=memories.filter(m=>filter==='Alle'||m.category===filter);$('#cards').innerHTML=list.map((m,i)=>`<article class="card" data-i="${memories.indexOf(m)}">${m.image?`<img src="${esc(m.image)}" alt="">`:''}<span class="tag">${esc(m.category)}</span><h3>${esc(m.title)}</h3>${m.quote?`<blockquote>“${esc(m.quote)}”</blockquote>`:''}<p>${esc(m.body).slice(0,180)}${m.body.length>180?'…':''}</p><small>${fmt(m.date)} · ${esc(m.author||'Anonym')}</small></article>`).join('');$$('.card[data-i]').forEach(c=>c.onclick=()=>show(memories[+c.dataset.i]))}function renderCalendar(){let y=view.getFullYear(),mo=view.getMonth();$('#monthTitle').textContent=new Intl.DateTimeFormat('de-CH',{month:'long',year:'numeric'}).format(view);let f=new Date(y,mo,1),off=(f.getDay()+6)%7,start=new Date(y,mo,1-off),h='';for(let i=0;i<42;i++){let d=new Date(start);d.setDate(start.getDate()+i);let di=iso(d),items=memories.filter(m=>m.date===di);h+=`<div class="day ${d.getMonth()!==mo?'muted':''} ${items.length?'has':''}" data-date="${di}"><b>${d.getDate()}</b>${items.slice(0,2).map(m=>`<span class="mini">${esc(m.title)}</span>`).join('')}</div>`}$('#calendar').innerHTML=h;$$('.day.has').forEach(e=>e.onclick=()=>showDay(e.dataset.date))}function flashback(){if(!memories.length)return;let n=new Date(),w=Math.floor((n-new Date(n.getFullYear(),0,1))/6048e5),m=memories[w%memories.length];$('#flashDay').textContent=new Date(m.date+'T12:00').getDate();$('#flashCat').textContent=m.category;$('#flashTitle').textContent=m.title;$('#flashQuote').textContent=m.quote||'';$('#flashBody').textContent=m.body;$('#flashMeta').textContent=`${fmt(m.date)} · ${m.author||'Anonym'}`}function show(m){if(!$('#modal'))return;$('#modalContent').innerHTML=`<span class="tag">${esc(m.category)}</span><h2>${esc(m.title)}</h2>${m.image?`<img src="${esc(m.image)}" alt="">`:''}${m.quote?`<blockquote>${esc(m.quote)}</blockquote>`:''}<p>${esc(m.body)}</p><small>${fmt(m.date)} · ${esc(m.author||'Anonym')}</small>`;$('#modal').showModal()}function showDay(d){let a=memories.filter(m=>m.date===d);$('#modalContent').innerHTML=`<span class="tag">${fmt(d)}</span>`+a.map(m=>`<h2>${esc(m.title)}</h2><p>${esc(m.body)}</p>`).join('<hr>');$('#modal').showModal()}if($('#prev'))$('#prev').onclick=()=>{view.setMonth(view.getMonth()-1);renderCalendar()};if($('#next'))$('#next').onclick=()=>{view.setMonth(view.getMonth()+1);renderCalendar()};if($('#close'))$('#close').onclick=()=>$('#modal').close();$$('.filters button').forEach(b=>b.onclick=()=>{$$('.filters button').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;renderCards()});init();